// #455: ребёнку i нужно печенье размера ≥ g[i]; накормить как можно больше детей
public int FindContentChildren(int[] g, int[] s) {
    Array.Sort(g); Array.Sort(s);
    int child = 0;
    foreach (int cookie in s)                                  // от маленького печенья к большому
        if (child < g.Length && cookie >= g[child]) child++;   // самому нетребовательному — первое подходящее
    return child;
}

